find:
delivery_log.push(
        recordDelivery({
          correlation_id: input.correlation_id,
          route_key: effective.route_key,
          destination_type: effective.destination_type,
          status,
          payload: status === 'SUCCESS' ? payload : null,
          retry_count,
        }),
      )

replace:
delivery_log.push(
        recordDelivery({
          correlation_id: input.correlation_id,
          route_key: effective.route_key,
          destination_type: effective.destination_type,
          // MUTATION M24: force SUCCESS
          status: 'SUCCESS',
          payload,
          retry_count,
        }),
      )
